<section class="page-hero shell trade-hero"><p class="kicker"><?=e($project['number'])?></p><h1><?=e($project['name'])?></h1><p><?=e($project['client'])?> · <?=e($project['location'])?></p><div class="hero-actions"><a class="btn outline" href="<?=e(url('/trade/projects/'.$project['guid'].'/export'))?>">Export BOQ CSV</a><a class="btn outline" href="<?=e(url('/trade'))?>">All projects</a></div></section><section class="section section-tight shell trade-project-layout"><div><div class="trade-boq"><div class="trade-boq-head"><strong>Product</strong><strong>Qty</strong><strong>List</strong><strong>Trade</strong><strong>Total</strong></div><?php foreach($project['lines'] as $l):?><div><span><strong><?=e($l['name'])?></strong><small><?=e($l['sku'])?></small></span><span><?=e((string)$l['qty'])?></span><span><?=money($l['list_price'])?></span><span><?=money($l['trade_unit_price'])?></span><span><?=money($l['trade_unit_price']*$l['qty'])?></span></div><?php endforeach;?></div><div class="trade-totals"><span>List <?=money($totals['list'])?></span><span>Trade <?=money($totals['trade'])?></span><strong>Saving <?=money($totals['saving'])?></strong></div></div><aside class="trade-add"><p class="kicker">Add to BOQ</p><form method="post" action="<?=e(url('/trade/projects/'.$project['guid'].'/add'))?>"><?=csrf_field()?><label>Product<select name="slug"><?php foreach($products as $p):?><option value="<?=e($p['slug'])?>"><?=e($p['name'])?> · <?=money(trade_price($p,$account))?></option><?php endforeach;?></select></label><label>Quantity<input type="number" name="qty" min="1" max="99" value="1"></label><label>Specification note<textarea name="notes" rows="4"></textarea></label><button class="btn dark">Add product</button></form></aside></section>
